In commit https://github.com/bitcoin/bitcoin/pull/36149/changes/12208a02ff5f795369fb2ab28884dc37b2db245d: _validation: don't change nSequenceId of a block that is a chain candidate_

Could we have a deterministic regression test for this, something like the unit test below? This would let us check that redownloading a block already in `setBlockIndexCandidates` preserves the set’s ordering, rather than relying on the fuzzer to hit the same sequence again.

```diff --git a/src/test/validation_chainstatemanager_tests.cpp b/src/test/validation_chainstatemanager_tests.cpp
index e150f317f4..112ea1fe0b 100644
--- a/src/test/validation_chainstatemanager_tests.cpp
+++ b/src/test/validation_chainstatemanager_tests.cpp
@@ -4,11 +4,13 @@
 //
 #include <chainparams.h>
 #include <consensus/validation.h>
+#include <flatfile.h>
 #include <kernel/disconnected_transactions.h>
 #include <node/block_template_manager.h>
 #include <node/chainstatemanager_args.h>
 #include <node/kernel_notifications.h>
 #include <node/utxo_snapshot.h>
+#include <primitives/block.h>
 #include <random.h>
 #include <rpc/blockchain.h>
 #include <sync.h>
@@ -27,6 +29,7 @@

 #include <tinyformat.h>

+#include <algorithm>
 #include <vector>

 #include <boost/test/unit_test.hpp>
@@ -37,6 +40,38 @@ using node::SnapshotMetadata;

 BOOST_FIXTURE_TEST_SUITE(validation_chainstatemanager_tests, TestingSetup)

+BOOST_FIXTURE_TEST_CASE(redownload_candidate_preserves_order, TestChain100Setup)
+{
+    auto& chainman = *Assert(m_node.chainman);
+    LOCK(::cs_main);
+    auto& candidates = chainman.ActiveChainstate().setBlockIndexCandidates;
+    CBlockIndex* tip = chainman.ActiveChain().Tip();
+
+    CBlockHeader header = tip->GetBlockHeader();
+    header.hashPrevBlock = tip->GetBlockHash();
+    header.nTime = tip->nTime + 1;
+    CBlock block;
+    block.vtx.resize(1);
+
+    header.nNonce = 1;
+    CBlockIndex* first = chainman.m_blockman.AddToBlockIndex(header, chainman.m_best_header);
+    chainman.ReceivedBlockTransactions(block, first, FlatFilePos{0, 1});
+    header.nNonce = 2;
+    CBlockIndex* second = chainman.m_blockman.AddToBlockIndex(header, chainman.m_best_header);
+    chainman.ReceivedBlockTransactions(block, second, FlatFilePos{0, 2});
+    BOOST_REQUIRE(candidates.contains(first));
+    BOOST_REQUIRE(candidates.contains(second));
+    BOOST_REQUIRE(first->nSequenceId < second->nSequenceId);
+    const size_t candidate_count = candidates.size();
+
+    // Redownload the earlier candidate, changing its sequence ID relative to the other one.
+    first->nStatus &= ~BLOCK_HAVE_DATA;
+    chainman.ReceivedBlockTransactions(block, first, FlatFilePos{0, 3});
+
+    BOOST_CHECK_EQUAL(candidates.size(), candidate_count);
+    BOOST_CHECK(std::is_sorted(candidates.begin(), candidates.end(), candidates.value_comp()));
+}
+
